159	/// Shared command-line option grammar for `sign` and `verify`.
160	///
161	/// Both subcommands accept the same two spellings for every option:
162	///   --name value     (the following argument is the value, even when it
163	///                    itself starts with "--")
164	///   --name=value     (everything after the first '=' is the value; further
165	///                    '=' characters stay part of the value)
166	/// and the two forms may be mixed freely.
167	///
168	/// What differs between the subcommands is only *which* option names are
169	/// allowed and whether a name may repeat, so each caller supplies its own
170	/// option table. Values that fail are never quoted back in error messages:
171	/// the messages name known options only, never the rejected text (which may
172	/// be a mistyped secret).
173	mod options {
174	    /// How many times an option name may appear on one command line.
175	    #[derive(Clone, Copy, PartialEq, Eq)]
176	    pub(super) enum Multiplicity {
177	        /// At most once; a second occurrence is a usage error.
178	        Single,
179	        /// Any number of times; values are kept in order of appearance.
180	        Repeated,
181	    }
182	
183	    /// One option accepted by a subcommand.
184	    pub(super) struct Spec {
185	        pub(super) name: &'static str,
186	        pub(super) multiplicity: Multiplicity,
187	    }
188	
189	    /// A matched option occurrence: the option's index in the table and its
190	    /// value for this occurrence.
191	    pub(super) struct Occurrence {
192	        pub(super) spec_index: usize,
193	        pub(super) value: String,
194	    }
195	
196	    /// Parse `args` against `specs`, preserving order of appearance.
197	    ///
198	    /// Error precedence (first problem wins, left to right):
199	    /// missing value for an option, repeated single-use option, unknown
200	    /// option or bare argument. Callers run their own semantic validation
201	    /// (hex, ranges, ...) afterwards, so grammar problems are always
202	    /// reported before invalid values.
203	    pub(super) fn parse(args: &[String], specs: &[Spec]) -> Result<Vec<Occurrence>, String> {
204	        let mut out = Vec::new();
205	        let mut seen_once = vec![false; specs.len()];
206	
207	        let mut i = 0;
208	        while i < args.len() {
209	            let arg = &args[i];
210	            // Support both "--opt value" and "--opt=value" forms. With '='
211	            // the value is everything after the FIRST '='; '=' characters
212	            // inside the value are left untouched.
213	            let (name, inline_value) = match arg.split_once('=') {
214	                Some((n, v)) if n.starts_with("--") => (n, Some(v.to_string())),
215	                _ => (arg.as_str(), None),
216	            };
217	            let spec_index = match specs.iter().position(|s| s.name == name) {
218	                Some(idx) => idx,
219	                // Never echo the unrecognized argument itself: it may be a
220	                // misplaced secret (e.g. a key value whose option name was
221	                // mistyped or whose value was consumed by another option).
222	                None => return Err(unknown_option_error(specs)),
223	            };
224	            let value = match inline_value {
225	                Some(v) => v,
226	                None => {
227	                    // The immediately following argument is the value, with
228	                    // no "--"-prefix special-casing: a field or key id may
229	                    // legitimately start with two dashes.
230	                    i += 1;
231	                    match args.get(i) {
232	                        Some(v) => v.clone(),
233	                        None => return Err(format!("option {name} requires a value")),
234	                    }
235	                }
236	            };
237	            if specs[spec_index].multiplicity == Multiplicity::Single && seen_once[spec_index] {
238	                return Err(format!("option {name} must be given exactly once"));
239	            }
240	            seen_once[spec_index] = true;
241	            out.push(Occurrence { spec_index, value });
242	            i += 1;
243	        }
244	        Ok(out)
245	    }
246	
247	    /// Build the fixed "unrecognized" message for a subcommand, listing only
248	    /// that subcommand's known option names. The rejected argument is never
249	    /// included.
250	    fn unknown_option_error(specs: &[Spec]) -> String {
251	        let names = specs
252	            .iter()
253	            .map(|s| s.name)
254	            .collect::<Vec<_>>()
255	            .join(", ");
256	        if specs.len() == 1 {
257	            format!("unrecognized option or argument (the only known option is {names})")
258	        } else {
259	            format!("unrecognized option or argument (known options: {names})")
260	        }
261	    }
262	}
263	
264	fn sign(args: &[String]) -> ExitCode {
265	    match parse_sign_args(args).and_then(validate_sign_args) {
266	        Ok(opts) => {
267	            let key_bytes = auth::decode_key(&opts.key);
268	            let key_version: u32 = opts.key_version.parse().expect("version was validated");
269	            let tag = auth::compute_tag(&key_bytes, &opts.key_id, key_version, &opts.fields);
270	            println!("{}", render_record(&opts.key_id, key_version, &opts.fields, &tag));
271	            ExitCode::SUCCESS
272	        }
273	        Err(msg) => {
274	            eprintln!("authnote sign: {msg}");
275	            ExitCode::from(2)
276	        }
277	    }
278	}
279	
280	/// Render one format-1 record as the single JSON line `sign` prints.
281	///
282	/// Pure presentation: member order, escaping, lowercase tag hex and the
283	/// trailing newline (added by the caller's `println!`) are fixed here. The
284	/// key is not a parameter — it never enters the record.
285	fn render_record(key_id: &str, key_version: u32, fields: &[String], tag: &auth::Tag) -> String {
286	    let fields_json = fields
287	        .iter()
288	        .map(|f| format!("\"{}\"", json_escape(f)))
289	        .collect::<Vec<_>>()
290	        .join(",");
291	    format!(
292	        "{{\"format\":{},\"algorithm\":\"{}\",\"key_id\":\"{}\",\"key_version\":{},\"fields\":[{}],\"tag\":\"{}\"}}",
293	        auth::FORMAT_VERSION,
294	        auth::ALGORITHM,
295	        json_escape(key_id),
296	        key_version,
297	        fields_json,
298	        auth::hex_encode(tag),
299	    )
300	}
301	
302	struct SignOptions {
303	    key: String,
304	    key_id: String,
305	    key_version: String,
306	    fields: Vec<String>,
307	}
308	
309	/// sign's option table: the three credential/metadata options are single
310	/// use; only --field may repeat. Names double as their stable indices.
311	const SIGN_OPTIONS: &[options::Spec] = &[
312	    options::Spec {
313	        name: "--key",
314	        multiplicity: options::Multiplicity::Single,
315	    },
316	    options::Spec {
317	        name: "--key-id",
318	        multiplicity: options::Multiplicity::Single,
319	    },
320	    options::Spec {
321	        name: "--key-version",
322	        multiplicity: options::Multiplicity::Single,
323	    },
324	    options::Spec {
325	        name: "--field",
326	        multiplicity: options::Multiplicity::Repeated,
327	    },
328	];
329	const SIGN_KEY_INDEX: usize = 0;
330	const SIGN_KEY_ID_INDEX: usize = 1;
331	const SIGN_KEY_VERSION_INDEX: usize = 2;
332	
333	fn parse_sign_args(args: &[String]) -> Result<SignOptions, String> {
334	    let mut key: Option<String> = None;
335	    let mut key_id: Option<String> = None;
336	    let mut key_version: Option<String> = None;
337	    let mut fields: Vec<String> = Vec::new();
338	
339	    for occurrence in options::parse(args, SIGN_OPTIONS)? {
340	        match occurrence.spec_index {
341	            SIGN_KEY_INDEX => key = Some(occurrence.value),
342	            SIGN_KEY_ID_INDEX => key_id = Some(occurrence.value),
343	            SIGN_KEY_VERSION_INDEX => key_version = Some(occurrence.value),
344	            // Field values are appended in order of appearance; repeats,
345	            // empty strings and text starting with "--" are kept verbatim.
346	            _ => fields.push(occurrence.value),
347	        }
348	    }
349	
350	    let key = key.ok_or("missing required option --key")?;
351	    let key_id = key_id.ok_or("missing required option --key-id")?;
352	    let key_version = key_version.ok_or("missing required option --key-version")?;
353	    Ok(SignOptions {
354	        key,
355	        key_id,
356	        key_version,
357	        fields,
358	    })
359	}
360	
361	fn validate_sign_args(opts: SignOptions) -> Result<SignOptions, String> {
362	    // Never echo the key back in error messages.
363	    auth::validate_key_hex(&opts.key)?;
364	    if opts.key_id.is_empty() {
365	        return Err("--key-id must not be empty".to_string());
366	    }
367	    let valid_version = !opts.key_version.is_empty()
368	        && opts.key_version.bytes().all(|b| b.is_ascii_digit())
369	        && opts
370	            .key_version
371	            .parse::<u64>()
372	            .is_ok_and(|v| (1..=u32::MAX as u64).contains(&v));
373	    if !valid_version {
374	        return Err("--key-version must be a decimal integer between 1 and 4294967295".to_string());
375	    }
376	    Ok(opts)
377	}
378	
379	// ---------------------------------------------------------------------------
380	// verify
381	// ---------------------------------------------------------------------------
382	
383	fn verify(args: &[String]) -> ExitCode {
384	    // verify deliberately shares sign's option grammar through the common
385	    // parser but declares its own, narrower table: --key is the only known
386	    // option, so every sign-only option (--key-id, --key-version, --field)
387	    // is rejected here as unrecognized. Values that fail are never echoed
388	    // (they could be a mistyped secret).
389	    const VERIFY_OPTIONS: &[options::Spec] = &[options::Spec {
390	        name: "--key",
391	        multiplicity: options::Multiplicity::Single,
392	    }];
393	
394	    let parse = (|| -> Result<String, String> {
395	        let occurrences = options::parse(args, VERIFY_OPTIONS)?;
396	        // The parser enforces "at most one --key"; take it if present.
397	        let key = occurrences
398	            .first()
399	            .map(|o| o.value.clone())
400	            .ok_or("missing required option --key")?;
401	        auth::validate_key_hex(&key)?;
402	        Ok(key)
403	    })();
404	
405	    let key_hex = match parse {
406	        Ok(key) => key,
407	        Err(msg) => {
408	            eprintln!("authnote verify: {msg}");
409	            return ExitCode::from(2);
410	        }
411	    };
412	
413	    // Read the whole standard input. It must be one JSON record and nothing
414	    // else; trailing non-whitespace is a malformed invocation, not a mismatch.
415	    let mut input = Vec::new();
416	    if let Err(e) = std::io::stdin().read_to_end(&mut input) {
417	        eprintln!("authnote verify: failed to read standard input: {e}");
418	        return ExitCode::from(2);
419	    }
420	
421	    let outcome = verify_input(&input, &key_hex);
422	    match outcome {
423	        VerifyOutcome::Valid => {
424	            println!("{{\"valid\":true}}");
425	            ExitCode::SUCCESS
426	        }
427	        VerifyOutcome::Mismatch => {
428	            println!("{{\"valid\":false}}");
429	            ExitCode::from(1)
430	        }
431	        VerifyOutcome::Invalid(msg) => {
432	            eprintln!("authnote verify: {msg}");
433	            ExitCode::from(2)
434	        }
435	    }
436	}
437	
438	#[derive(Debug)]
439	enum VerifyOutcome {
440	    Valid,
441	    Mismatch,
442	    Invalid(String),
443	}
444	
445	fn verify_input(input: &[u8], key_hex: &str) -> VerifyOutcome {
446	    let text = match std::str::from_utf8(input) {
447	        Ok(t) => t,
448	        // Still parse to distinguish a structurally invalid record from a
449	        // record whose text merely contains bytes Rust rejects; JSON itself
450	        // forbids raw non-UTF-8, so this is always "corrupt input" here.
451	        Err(_) => return VerifyOutcome::Invalid("input is not valid UTF-8 JSON text".to_string()),
452	    };
453	
454	    let value = match json::parse_single(text) {
455	        Ok(v) => v,
456	        Err(msg) => return VerifyOutcome::Invalid(msg),
457	    };
458	    let record = match record_from_json(&value) {
459	        Ok(r) => r,
460	        Err(msg) => return VerifyOutcome::Invalid(msg),
461	    };
462	
463	    let key_bytes = auth::decode_key(key_hex);
464	    let expected_tag = auth::compute_tag(
465	        &key_bytes,
466	        &record.key_id,
467	        record.key_version,
468	        &record.fields,
469	    );
470	
471	    if auth::tags_match(&expected_tag, &record.tag) {
472	        VerifyOutcome::Valid
473	    } else {
474	        VerifyOutcome::Mismatch
475	    }
476	}
477	
478	/// Decode the tag as exactly 32 bytes of case-insensitive hexadecimal.
479	fn decode_tag(s: &str) -> Result<Vec<u8>, String> {
480	    if s.len() != 64 || !s.bytes().all(|b| b.is_ascii_hexdigit()) {
481	        return Err("tag must be exactly 64 hexadecimal characters (32 bytes)".to_string());
482	    }
483	    auth::decode_hex(s).map_err(|e| format!("tag is not valid hexadecimal: {e}"))
484	}
485	
486	struct AuthRecord {
487	    key_id: String,
488	    key_version: u32,
489	    fields: Vec<String>,
490	    tag: Vec<u8>,
491	}
492	
493	/// Validate the decoded JSON value as exactly one format-1 authentication
494	/// record and pull out the authenticated fields. Structural problems (missing
495	/// members, wrong types, duplicates inside `fields`, ...) are caller errors:
496	/// they must produce exit 2, never a `{"valid":false}` mismatch result.
497	fn record_from_json(value: &json::JsonValue) -> Result<AuthRecord, String> {
498	    let obj = match value {
499	        json::JsonValue::Object(entries) => entries,
500	        _ => return Err("record must be a single JSON object".to_string()),
501	    };
502	
503	    // Require precisely the six documented members, each present exactly once;
504	    // the parser already rejects duplicate member names, and an empty object
505	    // naturally fails the "missing required member" checks below.
506	    let mut format: Option<&json::JsonValue> = None;
507	    let mut algorithm: Option<&json::JsonValue> = None;
508	    let mut key_id: Option<&json::JsonValue> = None;
509	    let mut key_version: Option<&json::JsonValue> = None;
510	    let mut fields: Option<&json::JsonValue> = None;
511	    let mut tag: Option<&json::JsonValue> = None;
512	    for (name, val) in obj {
513	        let slot = match name.as_str() {
514	            "format" => &mut format,
515	            "algorithm" => &mut algorithm,
516	            "key_id" => &mut key_id,
517	            "key_version" => &mut key_version,
518	            "fields" => &mut fields,
519	            "tag" => &mut tag,
520	            // Do not echo the unknown member name: it comes from the input
521	            // record, which error messages must never quote back.
522	            _ => return Err("record contains an unexpected member".to_string()),
523	        };
524	        if slot.is_some() {
525	            // The strict parser rejects duplicates already; keep a defense in
526	            // depth without quoting the member name from the input twice.
527	            return Err("record contains a duplicate member".to_string());
528	        }
529	        *slot = Some(val);
530	    }
531	
532	    // Unsupported format versions must be reported as such explicitly: we do
533	    // not silently fall back to the current rules and compute a result. The
534	    // decision is purely "is the integer spelling 1 or not", so zero, negative
535	    // and integers wider than the machine's usual integer capacity all say
536	    // "unsupported version" rather than "corrupt input"; non-integer spellings
537	    // (strings, fractions, exponents, leading zeros) stay type/grammar errors.
538	    let format = format.ok_or("record is missing required member \"format\"")?;
539	    match format {
540	        json::JsonValue::Number(n) if n.is_one() => {}
541	        json::JsonValue::Number(_) => {
542	            return Err("unsupported record format version; only format 1 is supported".to_string())
543	        }
544	        _ => return Err("member \"format\" must be an integer".to_string()),
545	    }
546	
547	    let algorithm = algorithm.ok_or("record is missing required member \"algorithm\"")?;
548	    match algorithm {
549	        json::JsonValue::String(s) if s == auth::ALGORITHM => {}
550	        json::JsonValue::String(_) => {
551	            return Err(
552	                "unsupported algorithm in record; only HMAC-SHA256 is supported".to_string(),
553	            )
554	        }
555	        _ => return Err("member \"algorithm\" must be a string".to_string()),
556	    }
557	
558	    let key_id = key_id.ok_or("record is missing required member \"key_id\"")?;
559	    let key_id = match key_id {
560	        json::JsonValue::String(s) if !s.is_empty() => s.clone(),
561	        json::JsonValue::String(_) => {
562	            return Err("member \"key_id\" must not be empty".to_string())
563	        }
564	        _ => return Err("member \"key_id\" must be a string".to_string()),
565	    };
566	
567	    let key_version = key_version.ok_or("record is missing required member \"key_version\"")?;
568	    let key_version = match key_version {
569	        json::JsonValue::Number(n) => {
570	            // Only the 1..=u32::MAX window is a legal key version. In
571	            // particular, an integer wider than `i128` stays an out-of-range
572	            // key version — it must never be misreported as an unsupported
573	            // record format.
574	            match n.as_i128() {
575	                Some(v) if (1..=i128::from(u32::MAX)).contains(&v) => v as u32,
576	                _ => {
577	                    return Err(
578	                        "member \"key_version\" is outside the supported range 1..=4294967295"
579	                            .to_string(),
580	                    )
581	                }
582	            }
583	        }
584	        _ => return Err("member \"key_version\" must be an integer".to_string()),
585	    };
586	
587	    let fields_val = fields.ok_or("record is missing required member \"fields\"")?;
588	    let fields = match fields_val {
589	        json::JsonValue::Array(items) => {
590	            let mut out = Vec::with_capacity(items.len());
591	            for item in items {
592	                match item {
593	                    json::JsonValue::String(s) => out.push(s.clone()),
594	                    _ => {
595	                        return Err(
596	                            "every element of member \"fields\" must be a string".to_string()
597	                        )
598	                    }
599	                }
600	            }
601	            out
602	        }
603	        _ => return Err("member \"fields\" must be an array of strings".to_string()),
604	    };
605	
606	    let tag_val = tag.ok_or("record is missing required member \"tag\"")?;
607	    let tag = match tag_val {
608	        json::JsonValue::String(s) => decode_tag(s)?,
609	        _ => return Err("member \"tag\" must be a string".to_string()),
610	    };
611	
612	    Ok(AuthRecord {
613	        key_id,
614	        key_version,
615	        fields,
616	        tag,
617	    })
618	}
619	
620	fn json_escape(s: &str) -> String {
621	    let mut out = String::with_capacity(s.len());
622	    for c in s.chars() {
623	        match c {
624	            '"' => out.push_str("\\\""),
625	            '\\' => out.push_str("\\\\"),
626	            '\n' => out.push_str("\\n"),
627	            '\r' => out.push_str("\\r"),
628	            '\t' => out.push_str("\\t"),
629	            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
630	            c => out.push(c),
631	        }
632	    }
633	    out
634	}
