636	// ---------------------------------------------------------------------------
637	// Strict JSON parser used by `verify`.
638	//
639	// Written by hand so the crate keeps zero third-party runtime dependencies.
640	// Unlike a tolerant parser it enforces every rule the verify contract relies
641	// on: exactly one complete value surrounded only by JSON whitespace, no
642	// duplicate member names within an object, strict number grammar (integers
643	// only, no fractions/exponents/leading zeros), strings decoded per RFC 8259
644	// including surrogate pairs. Anything it cannot parse is a corrupt record
645	// (exit 2), never a mismatch.
646	// ---------------------------------------------------------------------------
647	
648	mod json {
649	    /// An integer written with a legal JSON decimal spelling (optional sign,
650	    /// no leading zero, no fraction or exponent). The spelling is kept rather
651	    /// than the numeric value so integers wider than `i128` stay representable:
652	    /// a version field merely has to tell "1" apart from any other integer,
653	    /// which is a lexical decision and must never truncate or reject the value
654	    /// just because it is too large for the machine's widest integer.
655	    #[derive(Debug, PartialEq, Eq)]
656	    pub enum JsonInt {
657	        /// Integer that fits in `i128`; carries its exact value.
658	        Small(i128),
659	        /// Legal integer spelling that is outside the `i128` range, kept as
660	        /// its exact decimal text (including a leading '-'). Never truncated,
661	        /// rounded or treated as 1.
662	        Large(String),
663	    }
664	
665	    impl JsonInt {
666	        /// Parse a strictly-written JSON integer spelling (the caller has
667	        /// already enforced the grammar, including no leading zeros) without
668	        /// rejecting values wider than `i128`.
669	        fn from_strict_spelling(text: &str) -> JsonInt {
670	            match text.parse::<i128>() {
671	                Ok(n) => JsonInt::Small(n),
672	                // parse only fails here because the magnitude is out of range;
673	                // the spelling itself is valid JSON, so retain it verbatim.
674	                Err(_) => JsonInt::Large(text.to_string()),
675	            }
676	        }
677	
678	        /// Whether the integer is exactly the value 1: true only for the
679	        /// canonical spelling "1" (a `Large` value can never equal 1).
680	        pub fn is_one(&self) -> bool {
681	            matches!(self, JsonInt::Small(1))
682	        }
683	
684	        /// Exact value when it fits in `i128`; out-of-range spellings yield
685	        /// `None` instead of being truncated or wrapped.
686	        pub fn as_i128(&self) -> Option<i128> {
687	            match self {
688	                JsonInt::Small(n) => Some(*n),
689	                JsonInt::Large(_) => None,
690	            }
691	        }
692	    }
693	
694	    #[derive(Debug, PartialEq)]
695	    pub enum JsonValue {
696	        /// Parsed as an integer because the record grammar has no fractional
697	        /// values. Integers beyond `i128` stay legal JSON and are retained as
698	        /// their exact spelling (see `JsonInt::Large`).
699	        Number(JsonInt),
700	        String(String),
701	        Array(Vec<JsonValue>),
702	        /// Members kept in source order; names are unique (parser-enforced).
703	        Object(Vec<(String, JsonValue)>),
704	        // Accepted so documents using them parse, but records containing them
705	        // are rejected structurally by the caller.
706	        Bool(bool),
707	        Null,
708	    }
709	
710	    struct Parser<'a> {
711	        bytes: &'a [u8],
712	        pos: usize,
713	        /// Current object/array nesting depth, capped so adversarial input
714	        /// ("[[[[...")") cannot exhaust the stack and crash the verifier.
715	        depth: usize,
716	    }
717	
718	    /// Far above the depth a real record ever reaches (record → `fields`
719	    /// array → string is depth 2) while staying well within stack limits.
720	    const MAX_DEPTH: usize = 64;
721	
722	    /// Parse exactly one JSON value: optional leading/trailing JSON whitespace
723	    /// is allowed, but any trailing non-whitespace content (including a second
724	    /// object) is an error.
725	    pub fn parse_single(input: &str) -> Result<JsonValue, String> {
726	        let mut p = Parser {
727	            bytes: input.as_bytes(),
728	            pos: 0,
729	            depth: 0,
730	        };
731	        p.skip_ws();
732	        if p.pos == p.bytes.len() {
733	            return Err("input is empty; expected one JSON record".to_string());
734	        }
735	        let value = p.parse_value()?;
736	        p.skip_ws();
737	        if p.pos != p.bytes.len() {
738	            return Err(
739	                "trailing non-whitespace content after record; exactly one JSON object is allowed"
740	                    .to_string(),
741	            );
742	        }
743	        Ok(value)
744	    }
745	
746	    impl<'a> Parser<'a> {
747	        fn skip_ws(&mut self) {
748	            while self.pos < self.bytes.len()
749	                && matches!(self.bytes[self.pos], b' ' | b'\t' | b'\n' | b'\r')
750	            {
751	                self.pos += 1;
752	            }
753	        }
754	
755	        fn peek(&self) -> Option<u8> {
756	            self.bytes.get(self.pos).copied()
757	        }
758	
759	        fn enter_container(&mut self) -> Result<(), String> {
760	            if self.depth >= MAX_DEPTH {
761	                return Err("JSON nesting is too deep".to_string());
762	            }
763	            self.depth += 1;
764	            Ok(())
765	        }
766	
767	        fn parse_value(&mut self) -> Result<JsonValue, String> {
768	            self.skip_ws();
769	            match self.peek() {
770	                Some(b'{') => self.parse_object(),
771	                Some(b'[') => self.parse_array(),
772	                Some(b'"') => Ok(JsonValue::String(self.parse_string()?)),
773	                Some(b't') => self.parse_lit("true", JsonValue::Bool(true)),
774	                Some(b'f') => self.parse_lit("false", JsonValue::Bool(false)),
775	                Some(b'n') => self.parse_lit("null", JsonValue::Null),
776	                Some(c) if c == b'-' || c.is_ascii_digit() => self.parse_number(),
777	                Some(_) => Err("unexpected character while parsing JSON".to_string()),
778	                None => Err("unexpected end of JSON input".to_string()),
779	            }
780	        }
781	
782	        fn parse_lit(&mut self, lit: &str, value: JsonValue) -> Result<JsonValue, String> {
783	            if self.bytes[self.pos..].starts_with(lit.as_bytes()) {
784	                self.pos += lit.len();
785	                Ok(value)
786	            } else {
787	                Err("malformed JSON literal".to_string())
788	            }
789	        }
790	
791	        fn parse_object(&mut self) -> Result<JsonValue, String> {
792	            self.enter_container()?;
793	            let result = self.parse_object_inner();
794	            self.depth -= 1;
795	            result
796	        }
797	
798	        fn parse_object_inner(&mut self) -> Result<JsonValue, String> {
799	            self.pos += 1; // '{'
800	            let mut entries: Vec<(String, JsonValue)> = Vec::new();
801	            self.skip_ws();
802	            if self.peek() == Some(b'}') {
803	                self.pos += 1;
804	                return Ok(JsonValue::Object(entries));
805	            }
806	            loop {
807	                self.skip_ws();
808	                if self.peek() != Some(b'"') {
809	                    return Err("expected a string member name in JSON object".to_string());
810	                }
811	                let name = self.parse_string()?;
812	                self.skip_ws();
813	                if self.peek() != Some(b':') {
814	                    return Err("expected ':' after JSON member name".to_string());
815	                }
816	                self.pos += 1;
817	                let value = self.parse_value()?;
818	                if entries.iter().any(|(n, _)| *n == name) {
819	                    return Err("JSON object contains a duplicate member".to_string());
820	                }
821	                entries.push((name, value));
822	                self.skip_ws();
823	                match self.peek() {
824	                    Some(b',') => {
825	                        self.pos += 1;
826	                    }
827	                    Some(b'}') => {
828	                        self.pos += 1;
829	                        break;
830	                    }
831	                    Some(_) => return Err("expected ',' or '}}' in JSON object".to_string()),
832	                    None => return Err("unterminated JSON object".to_string()),
833	                }
834	            }
835	            Ok(JsonValue::Object(entries))
836	        }
837	
838	        fn parse_array(&mut self) -> Result<JsonValue, String> {
839	            self.enter_container()?;
840	            let result = self.parse_array_inner();
841	            self.depth -= 1;
842	            result
843	        }
844	
845	        fn parse_array_inner(&mut self) -> Result<JsonValue, String> {
846	            self.pos += 1; // '['
847	            let mut items = Vec::new();
848	            self.skip_ws();
849	            if self.peek() == Some(b']') {
850	                self.pos += 1;
851	                return Ok(JsonValue::Array(items));
852	            }
853	            loop {
854	                items.push(self.parse_value()?);
855	                self.skip_ws();
856	                match self.peek() {
857	                    Some(b',') => {
858	                        self.pos += 1;
859	                        self.skip_ws();
860	                    }
861	                    Some(b']') => {
862	                        self.pos += 1;
863	                        break;
864	                    }
865	                    Some(_) => return Err("expected ',' or ']' in JSON array".to_string()),
866	                    None => return Err("unterminated JSON array".to_string()),
867	                }
868	            }
869	            Ok(JsonValue::Array(items))
870	        }
871	
872	        fn parse_string(&mut self) -> Result<String, String> {
873	            self.pos += 1; // opening quote
874	            let mut out = String::new();
875	            loop {
876	                match self.peek() {
877	                    None => return Err("unterminated JSON string".to_string()),
878	                    Some(b'"') => {
879	                        self.pos += 1;
880	                        break;
881	                    }
882	                    Some(b'\\') => {
883	                        self.pos += 1;
884	                        let esc = self
885	                            .peek()
886	                            .ok_or("unterminated JSON escape sequence")?;
887	                        self.pos += 1;
888	                        match esc {
889	                            b'"' => out.push('"'),
890	                            b'\\' => out.push('\\'),
891	                            b'/' => out.push('/'),
892	                            b'b' => out.push('\u{0008}'),
893	                            b'f' => out.push('\u{000c}'),
894	                            b'n' => out.push('\n'),
895	                            b'r' => out.push('\r'),
896	                            b't' => out.push('\t'),
897	                            b'u' => {
898	                                let hi = self.parse_hex4()?;
899	                                let c = if (0xD800..=0xDBFF).contains(&hi) {
900	                                    // High surrogate must be followed by "\uXXXX"
901	                                    // low surrogate; lone surrogates are invalid.
902	                                    if self.peek() != Some(b'\\') {
903	                                        return Err(
904	                                            "lone UTF-16 high surrogate in JSON string".to_string()
905	                                        );
906	                                    }
907	                                    self.pos += 1;
908	                                    if self.peek() != Some(b'u') {
909	                                        return Err(
910	                                            "bad surrogate pair escape in JSON string".to_string()
911	                                        );
912	                                    }
913	                                    self.pos += 1;
914	                                    let lo = self.parse_hex4()?;
915	                                    if !(0xDC00..=0xDFFF).contains(&lo) {
916	                                        return Err(
917	                                            "low surrogate out of range in JSON string".to_string()
918	                                        );
919	                                    }
920	                                    char::from_u32(0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00))
921	                                        .ok_or("invalid surrogate pair in JSON string")?
922	                                } else if (0xDC00..=0xDFFF).contains(&hi) {
923	                                    return Err(
924	                                        "lone UTF-16 low surrogate in JSON string".to_string()
925	                                    );
926	                                } else {
927	                                    char::from_u32(hi)
928	                                        .ok_or("invalid unicode escape in JSON string")?
929	                                };
930	                                out.push(c);
931	                            }
932	                            _ => {
933	                                return Err("invalid escape sequence in JSON string".to_string())
934	                            }
935	                        }
936	                    }
937	                    Some(c) if c < 0x20 => {
938	                        return Err("unescaped control character in JSON string".to_string())
939	                    }
940	                    Some(_) => {
941	                        // Copy one whole UTF-8 scalar at a time, validating that
942	                        // the raw bytes really are UTF-8 (the surrounding input
943	                        // is &str so this cannot fail, but keep the boundary
944	                        // explicit rather than slicing mid-char).
945	                        let start = self.pos;
946	                        self.pos += 1;
947	                        while self.pos < self.bytes.len() {
948	                            let b = self.bytes[self.pos];
949	                            if b == b'"' || b == b'\\' || b < 0x20 {
950	                                break;
951	                            }
952	                            self.pos += 1;
953	                        }
954	                        let chunk = std::str::from_utf8(&self.bytes[start..self.pos])
955	                            .map_err(|_| "invalid UTF-8 inside JSON string".to_string())?;
956	                        out.push_str(chunk);
957	                    }
958	                }
959	            }
960	            Ok(out)
961	        }
962	
963	        fn parse_hex4(&mut self) -> Result<u32, String> {
964	            let mut v = 0u32;
965	            for _ in 0..4 {
966	                if self.peek().is_none() {
967	                    return Err("truncated \\u escape in JSON string".to_string());
968	                }
969	                let c = self.peek().unwrap();
970	                if !(c as char).is_ascii_hexdigit() {
971	                    return Err("bad hexadecimal digit in \\u escape".to_string());
972	                }
973	                let d = (c as char).to_digit(16).unwrap();
974	                self.pos += 1;
975	                v = v * 16 + d;
976	            }
977	            Ok(v)
978	        }
979	
980	        /// Strict RFC 8259 integer grammar. The record format has no fractional
981	        /// values, so `.`/`e` forms are rejected rather than truncated. A
982	        /// syntactically legal integer is never rejected for being wider than
983	        /// `i128`: it is retained verbatim so callers can classify it (for
984	        /// example, an unsupported format version) without truncating the
985	        /// value or confusing it with corrupt JSON.
986	        fn parse_number(&mut self) -> Result<JsonValue, String> {
987	            let start = self.pos;
988	            if self.peek() == Some(b'-') {
989	                self.pos += 1;
990	            }
991	            match self.peek() {
992	                Some(b'0') => {
993	                    self.pos += 1;
994	                    // A leading zero must not be followed by more digits.
995	                    if matches!(self.peek(), Some(c) if c.is_ascii_digit()) {
996	                        return Err("numbers with leading zeros are not valid JSON".to_string());
997	                    }
998	                }
999	                Some(c) if c.is_ascii_digit() => {
1000	                    while matches!(self.peek(), Some(c) if c.is_ascii_digit()) {
1001	                        self.pos += 1;
1002	                    }
1003	                }
1004	                _ => return Err("malformed JSON number".to_string()),
1005	            }
1006	            // No fraction or exponent: this grammar only carries integers.
1007	            if matches!(self.peek(), Some(b'.' | b'e' | b'E')) {
1008	                return Err(
1009	                    "record numbers must be integers; fractions and exponents are not accepted"
1010	                        .to_string(),
1011	                );
1012	            }
1013	            let text = std::str::from_utf8(&self.bytes[start..self.pos])
1014	                .map_err(|_| "invalid UTF-8 in JSON number".to_string())?;
1015	            Ok(JsonValue::Number(JsonInt::from_strict_spelling(text)))
1016	        }
1017	    }
1018	}
