1099	    /// Build a format-1 record JSON string for the given content, with the
1100	    /// correct tag for `key`.
1101	    fn record_for(key_hex: &str, key_id: &str, version: u32, fields: &[&str]) -> String {
1102	        let tag = sign_tag(key_hex, key_id, version, fields);
1103	        let fields_json = fields
1104	            .iter()
1105	            .map(|f| format!("\"{}\"", json_escape(f)))
1106	            .collect::<Vec<_>>()
1107	            .join(",");
1108	        format!(
1109	            "{{\"format\":1,\"algorithm\":\"HMAC-SHA256\",\"key_id\":\"{}\",\"key_version\":{},\"fields\":[{}],\"tag\":\"{}\"}}",
1110	            json_escape(key_id),
1111	            version,
1112	            fields_json,
1113	            tag
1114	        )
1115	    }
