256	#[test]
257	fn verify_crossing_empty_field_encodings_fails() {
258	    let key = "00ff";
259	    let zero = sign_record_bytes(key, "id", "1", &[]);
260	    let one_empty = sign_record_bytes(key, "id", "1", &[""]);
261	
262	    // Put the empty-field record's tag onto the zero-field record.
263	    let zero_obj = Json::parse(std::str::from_utf8(&zero).unwrap().trim_end_matches('\n'));
264	    let empty_tag = Json::parse(std::str::from_utf8(&one_empty).unwrap().trim_end_matches('\n'))
265	        .get("tag")
266	        .as_str()
267	        .to_string();
268	    let crossed: Vec<(String, Json)> = zero_obj
269	        .as_object()
270	        .iter()
271	        .map(|(k, v)| {
272	            if k == "tag" {
273	                (k.clone(), Json::Str(empty_tag.clone()))
274	            } else {
275	                (k.clone(), v.clone())
276	            }
277	        })
278	        .collect();
279	    let out = run_verify(key, (json_value_to_text(&Json::Obj(crossed)) + "\n").as_bytes());
280	    assert_eq!(out.status.code(), Some(1));
281	    assert_eq!(out.stdout, b"{\"valid\":false}\n");
282	}
283	
284	// ---------------------------------------------------------------------------
285	// verify: invalid record / invocation path (exit 2, empty stdout)
286	// ---------------------------------------------------------------------------
287	
288	fn expect_verify_invalid(input: &[u8], args: &[&str]) -> String {
289	    let out = run_verify_raw(args, input);
290	    assert_eq!(
291	        out.status.code(),
292	        Some(2),
293	        "expected exit 2, stdout={:?}, stderr={:?}",
294	        String::from_utf8_lossy(&out.stdout),
295	        String::from_utf8_lossy(&out.stderr)
296	    );
297	    assert!(out.stdout.is_empty(), "stdout must be empty on exit 2");
298	    let stderr = String::from_utf8(out.stderr).expect("stderr must be UTF-8");
299	    assert!(!stderr.trim().is_empty(), "stderr must explain the problem");
300	    stderr
301	}
302	
303	#[test]
304	fn verify_rejects_multiple_records_and_trailing_garbage() {
305	    let key = "00ff";
306	    let rec = sign_record_bytes(key, "id", "1", &["x"]);
307	
308	    let mut two = rec.clone();
309	    two.extend_from_slice(&rec);
310	    expect_verify_invalid(&two, &["--key", key]);
311	
312	    let mut with_word = rec.clone();
313	    with_word.extend_from_slice(b" x");
314	    expect_verify_invalid(&with_word, &["--key", key]);
315	
316	    let mut with_num = rec.clone();
317	    with_num.extend_from_slice(b"42");
318	    expect_verify_invalid(&with_num, &["--key", key]);
319	
320	    expect_verify_invalid(b"", &["--key", key]);
321	    expect_verify_invalid(b"   \n\t", &["--key", key]);
322	}
323	
324	#[test]
325	fn verify_rejects_corrupt_and_ill_typed_records() {
