349	// ---------------------------------------------------------------------------
350	// verify: key_version regression coverage
351	//
352	// The key version participates in the authenticated content AND is constrained
353	// by the record grammar, so callers must be able to tell apart:
354	//   * a structurally legal record whose tag does not match (exit 1), and
355	//   * a record whose key_version spelling or range is illegal (exit 2).
356	// Every tag below is an independent Python golden over the format-1 contract
357	// in README.md (key 00ff, key_id "kidprobe", one field "verprobe"); `sign` is
358	// not used to produce the boundary/mismatch records, so a shared sign/verify
359	// bug cannot make these pass.
360	// ---------------------------------------------------------------------------
361	
362	const KV_KEY: &str = "00ff";
363	/// A different but well-formed key: choosing the wrong key must turn a
364	/// structurally legal record into a mismatch, never into corrupt input.
365	const KV_WRONG_KEY: &str = "0102";
366	const KV_KID: &str = "kidprobe";
367	const KV_FIELD: &str = "verprobe";
368	/// Golden tag at version 1 (the range's low endpoint).
369	const KV_TAG_V1: &str = "4301ff56f516eef690d78758c6fd0311d90391920d1b4a5eddd0cdc2966e4a53";
370	/// Golden tag at version 4294967295 (the range's high endpoint, u32::MAX).
371	const KV_TAG_VMAX: &str = "5760ad7d9bfc942d2754bce443165a5db296460b9401a4dea878137d9b960e64";
372	/// Golden tag at version 7 (what `sign --key-version 007` must authenticate).
373	const KV_TAG_V7: &str = "deabcb0017a1462e2d59490a499830033877d4b13450f8a502e5cea18e4dc798";
374	
375	/// Hand-author a record with an arbitrary *raw* `key_version` token (which may
376	/// be illegal JSON) and an arbitrary tag.
377	fn kv_record(version_token: &str, tag: &str) -> String {
378	    format!(
379	        r#"{{"format":1,"algorithm":"HMAC-SHA256","key_id":"{KV_KID}","key_version":{version_token},"fields":["{KV_FIELD}"],"tag":"{tag}"}}"#
380	    )
381	}
