1097	/// Successful invocation: exit code 0, empty stderr, one valid record whose
1098	/// fields/key-id/version match the inputs and whose tag equals the golden
1099	/// value computed independently of this implementation.
1100	fn expect_signed_record(
1101	    label: &str,
1102	    key: &str,
1103	    key_id: &str,
1104	    version: &str,
1105	    fields: &[&str],
1106	    golden_tag: &str,
1107	) -> Record {
1108	    let out = run_sign(key, key_id, version, fields);
1109	    assert_eq!(
1110	        out.status.code(),
1111	        Some(0),
1112	        "{label}: expected exit 0, got {:?}, stderr={:?}",
1113	        out.status.code(),
1114	        String::from_utf8_lossy(&out.stderr)
1115	    );
1116	    assert!(
1117	        out.stderr.is_empty(),
1118	        "{label}: stderr must be empty, got {:?}",
1119	        String::from_utf8_lossy(&out.stderr)
1120	    );
1121	
1122	    let rec = parse_single_record(&out.stdout);
1123	    assert_eq!(rec.tag, golden_tag, "{label}: tag mismatch");
1124	    assert_eq!(rec.key_id, key_id, "{label}: key_id mismatch");
1125	    assert_eq!(
1126	        rec.key_version,
1127	        version.parse::<i64>().unwrap(),
1128	        "{label}: key_version mismatch"
1129	    );
1130	    assert_eq!(
1131	        rec.fields,
1132	        fields.iter().map(|s| s.to_string()).collect::<Vec<_>>(),
1133	        "{label}: parsed fields must be character-identical to the inputs"
1134	    );
1135	
1136	    // The raw key is used only for the MAC: it must never appear as a value
1137	    // anywhere in the record (compared as a whole string, not a substring, so
1138	    // short keys cannot clash with random fragments of the 64-char tag).
1139	    let needle = key.to_lowercase();
1140	    let mut strings = Vec::new();
1141	    rec.raw.strings(&mut strings);
1142	    assert!(
1143	        strings.iter().all(|s| s.to_lowercase() != needle),
1144	        "{label}: raw key material must not be part of the record"
1145	    );
1146	    rec
1147	}
